import{_ as a,H as e,f as r,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"基础通关 | 线性代数5道典型例题及解析","description":"","frontmatter":{},"headers":[{"level":2,"title":"例题一","slug":"例题一","link":"#例题一","children":[{"level":3,"title":"解析：","slug":"解析","link":"#解析","children":[]}]},{"level":2,"title":"例题二","slug":"例题二","link":"#例题二","children":[{"level":3,"title":"解析：","slug":"解析-1","link":"#解析-1","children":[]}]},{"level":2,"title":"例题三","slug":"例题三","link":"#例题三","children":[{"level":3,"title":"解析：","slug":"解析-2","link":"#解析-2","children":[]}]},{"level":2,"title":"例题四","slug":"例题四","link":"#例题四","children":[{"level":3,"title":"解析：","slug":"解析-3","link":"#解析-3","children":[]}]},{"level":2,"title":"例题五","slug":"例题五","link":"#例题五","children":[{"level":3,"title":"解析：","slug":"解析-4","link":"#解析-4","children":[]}]}],"relativePath":"重学线性代数/基础通关-线性代数5道典型例题及解析.md","filePath":"重学线性代数/基础通关-线性代数5道典型例题及解析.md","lastUpdated":1779822691000}'),i={name:"重学线性代数/基础通关-线性代数5道典型例题及解析.md"};function t(n,p,$,m,h,c){return e(),r("div",null,[...p[0]||(p[0]=[l('<h1 id="基础通关-线性代数5道典型例题及解析" tabindex="-1">基础通关 | 线性代数5道典型例题及解析 <a class="header-anchor" href="#基础通关-线性代数5道典型例题及解析" aria-label="Permalink to &quot;基础通关 | 线性代数5道典型例题及解析&quot;">​</a></h1><p>你好，我是朱维刚。欢迎你继续跟我学习线性代数。</p><p>今天这一节课的内容是基础通关。这里会用5道典型例题，让你巩固一下线性代数的基础知识，这也是进入应用篇学习之前的一次动手机会。从课程上线到现在快有一个月了，这期间我收到了不少同学的提问和建议，有些问题也是我没有想到的，非常有深度，说实话这让我感觉挺意外的，希望你再接再厉。</p><p>现在，你可以看一下基础通关的5道例题了，题目和解析都放在了正文中，你可以自己试着做一下。基础通关后，我们应用篇再见。</p><h2 id="例题一" tabindex="-1">例题一 <a class="header-anchor" href="#例题一" aria-label="Permalink to &quot;例题一&quot;">​</a></h2><p>找到线性方程组$Ax=b$的所有解，其中：</p><p>$$</p><p>A=\\left[\\begin{array}{cc}</p><p>1 &amp; 2 \\\\</p><p>3 &amp; 0 \\\\</p><p>-1 &amp; 2</p><p>\\end{array}\\right], b=\\left[\\begin{array}{c}</p><p>1 \\\\</p><p>0 \\\\</p><p>1</p><p>\\end{array}\\right]</p><p>$$</p><h3 id="解析" tabindex="-1">解析： <a class="header-anchor" href="#解析" aria-label="Permalink to &quot;解析：&quot;">​</a></h3><p>这里考察了解线性方程组的方法，特别是高斯消元法，你可以参考第4节的内容。</p><p>首先，形成增广矩阵：</p><p>$$</p><p>\\left[\\begin{array}{cccc}</p><p>1 &amp; 2 &amp; 1 \\\\</p><p>3 &amp; 0 &amp; 0 \\\\</p><p>-1 &amp; 2 &amp; 1</p><p>\\end{array}\\right]</p><p>$$</p><p>接着，分步计算增广矩阵的行阶梯形矩阵：</p><ol><li>第一行乘-3和第二行相加。</li><li>第一行和第三行相加。</li></ol><p>$$</p><p>\\left[\\begin{array}{cccc}</p><p>1 &amp; 2 &amp; 1 \\\\</p><p>0 &amp; -6 &amp; -3 \\\\</p><p>0 &amp; 4 &amp; 2</p><p>\\end{array}\\right]</p><p>$$</p><ol start="2"><li>第二行乘$\\frac{1}{3}$和第一行相加。</li><li>第二行乘$\\frac{2}{3}$和第三行相加。</li><li>第三行乘$-\\frac{1}{6}$。</li></ol><p>$$</p><p>\\left[\\begin{array}{llll}</p><p>1 &amp; 0 &amp; 0 \\\\</p><p>0 &amp; 1 &amp; \\frac{1}{2} \\\\</p><p>0 &amp; 0 &amp; 0</p><p>\\end{array}\\right]</p><p>$$</p><p>最后得出该线性方程组的唯一解：</p><p>$$</p><p>x=\\left[\\begin{array}{l}</p><p>0 \\\\</p><p>\\frac{1}{2}</p><p>\\end{array}\\right]</p><p>$$</p><h2 id="例题二" tabindex="-1">例题二 <a class="header-anchor" href="#例题二" aria-label="Permalink to &quot;例题二&quot;">​</a></h2><p>找到线性方程组$Ax=b$的所有解，其中：</p><p>$$</p><p>A=\\left[\\begin{array}{lll}</p><p>1 &amp; 2 &amp; 3 \\\\</p><p>0 &amp; 2 &amp; 2</p><p>\\end{array}\\right], b=\\left[\\begin{array}{l}</p><p>1 \\\\</p><p>1</p><p>\\end{array}\\right]</p><p>$$</p><h3 id="解析-1" tabindex="-1">解析： <a class="header-anchor" href="#解析-1" aria-label="Permalink to &quot;解析：&quot;">​</a></h3><p>这里考察了解线性方程组的方法，特别是高斯消元法。你可以参考第4节的内容，和例题一不同的是，例题二这里得到的会是无穷解。所以，这一题里找特殊解和通用解的方法是关键。</p><p>首先，形成增广矩阵：</p><p>$$</p><p>\\left[\\begin{array}{lllll}</p><p>1 &amp; 2 &amp; 3 &amp; 1 &amp; 1 \\\\</p><p>0 &amp; 2 &amp; 2 &amp; 1 &amp; 1</p><p>\\end{array}\\right]</p><p>$$</p><p>接着，形成增广矩阵：分步计算增广矩阵的行阶梯形矩阵：</p><ol><li>第一行乘-1和第二行相加；</li><li>第二行乘1/2。</li></ol><p>$$</p><p>\\left[\\begin{array}{lllll}</p><p>1 &amp; 0 &amp; 1 &amp; 1 &amp; 0 \\\\</p><p>0 &amp; 1 &amp; 1 &amp; 1 &amp; \\frac{1}{2}</p><p>\\end{array}\\right]</p><p>$$</p><p>使用主元列，得到特殊解：</p><p>$$</p><p>x=\\left[\\begin{array}{l}</p><p>0 \\\\</p><p>\\frac{1}{2} \\\\</p><p>0</p><p>\\end{array}\\right]</p><p>$$</p><p>下一步，获取线性方程组$Ax=0$的通用解，从增广矩阵的左边，能够立即得出：</p><p>$$</p><p>\\lambda\\left[\\begin{array}{c}</p><p>1 \\\\</p><p>1 \\\\</p><p>-1</p><p>\\end{array}\\right]</p><p>$$</p><p>最后，把特殊解和通用解组合起来就是：</p><p>$$</p><p>x=\\left[\\begin{array}{l}</p><p>0 \\\\</p><p>\\frac{1}{2} \\\\</p><p>0</p><p>\\end{array}\\right]+\\lambda\\left[\\begin{array}{c}</p><p>1 \\\\</p><p>1 \\\\</p><p>-1</p><p>\\end{array}\\right]</p><p>$$</p><h2 id="例题三" tabindex="-1">例题三 <a class="header-anchor" href="#例题三" aria-label="Permalink to &quot;例题三&quot;">​</a></h2><p>计算矩阵乘$AB$。</p><p>$$</p><p>A=\\left[\\begin{array}{ccc}</p><p>1 &amp; 2 &amp; 3 \\\\</p><p>0 &amp; -1 &amp; 2</p><p>\\end{array}\\right], B=\\left[\\begin{array}{ccc}</p><p>4 &amp; -1 &amp; 2 \\\\</p><p>0 &amp; 2 &amp; 1</p><p>\\end{array}\\right]</p><p>$$</p><h3 id="解析-2" tabindex="-1">解析： <a class="header-anchor" href="#解析-2" aria-label="Permalink to &quot;解析：&quot;">​</a></h3><p>这里考察了基本的矩阵乘运算，特别是普通矩阵乘，只有相邻阶数匹配的矩阵才能相乘，你可以参考第3节的内容。</p><p>矩阵乘无法完成，因为$A$是2行3列矩阵，$B$也是2行3列矩阵，$A$和邻居维度不同。</p><h2 id="例题四" tabindex="-1">例题四 <a class="header-anchor" href="#例题四" aria-label="Permalink to &quot;例题四&quot;">​</a></h2><p>计算矩阵乘$AB$。</p><p>$$</p><p>A=\\left[\\begin{array}{ccc}</p><p>1 &amp; 2 &amp; 3 \\\\</p><p>0 &amp; -1 &amp; 2</p><p>\\end{array}\\right], B=\\left[\\begin{array}{cc}</p><p>4 &amp; -1 \\\\</p><p>2 &amp; 0 \\\\</p><p>2 &amp; 1</p><p>\\end{array}\\right]</p><p>$$</p><h3 id="解析-3" tabindex="-1">解析： <a class="header-anchor" href="#解析-3" aria-label="Permalink to &quot;解析：&quot;">​</a></h3><p>这里考察了基本的矩阵乘运算，特别是普通矩阵乘，你可以参考第3节的内容。</p><p>矩阵乘可以完成，因为两个矩阵的邻居维度相同，拿$a_{11}$举例：$a_{11}=1 \\times 4+2 \\times 2+3 \\times 2=14$，结果：</p><p>$$</p><p>A B=\\left[\\begin{array}{cc}</p><p>14 &amp; 2 \\\\</p><p>2 &amp; 2</p><p>\\end{array}\\right]</p><p>$$</p><h2 id="例题五" tabindex="-1">例题五 <a class="header-anchor" href="#例题五" aria-label="Permalink to &quot;例题五&quot;">​</a></h2><p>假设$R^{3}$和它的运算$\\langle\\ ·,· \\rangle$，$x, y \\in R^{3}$，我们有：</p><p>$$</p><p>\\langle x, y\\rangle=x^{T} A y, A=\\left[\\begin{array}{ccc}</p><p>4 &amp; 2 &amp; 1 \\\\</p><p>0 &amp; 4 &amp; -1 \\\\</p><p>1 &amp; -1 &amp; 5</p><p>\\end{array}\\right]</p><p>$$</p><p>那么，$\\langle\\ ·,· \\rangle$是内积吗？</p><h3 id="解析-4" tabindex="-1">解析： <a class="header-anchor" href="#解析-4" aria-label="Permalink to &quot;解析：&quot;">​</a></h3><p>这里考察了内积，以及内积的性质之一：对称性，你可以参考第10节的内容。</p><p>选择$x=\\left[\\begin{array}{lll}1 &amp; 1 &amp; 0\\end{array}\\right]^{T}$，$y=\\left[\\begin{array}{lll}1 &amp; 2 &amp; 0\\end{array}\\right]^{T}$，通过计算，能够得到：</p><p>$$</p><p>\\begin{array}{l}</p><p>\\langle x, y\\rangle=16 \\\\</p><p>\\langle y, x\\rangle=14 \\\\</p><p>\\langle x, y\\rangle \\neq\\langle y, x\\rangle</p><p>\\end{array}</p><p>$$</p><p>于是，$\\langle\\ ·,· \\rangle$是不对称的。</p>',163)])])}const o=a(i,[["render",t]]);export{g as __pageData,o as default};
